import pandas as pd
import statsmodels.formula.api as smf

port = pd.read_csv("fin400-port-pe.csv", parse_dates=["caldt"])
fac = pd.read_csv("fin400-factors.csv", parse_dates=["caldt"])
data = pd.merge(port, fac, on="caldt", how="inner")

results = {}
for name in ["p0", "p1", "p2", "p3", "p4"]:
    results = {}
    results[name] = smf.ols(f"{name} ~ mkt + small", data=data).fit().params

print(sorted(results))
